situ_err_t fzn_exif_ifd_entry_validate(situ_view_t view, uint16_t arg_order);

/* ---- struct ifd ---- */

#define FZN_EXIF_IFD_SIZE_MIN   6u
#define FZN_EXIF_IFD_SIZE_MAX   786426u

/* INVALIDATION: a ifd view, and every view derived from
 * it, is invalidated by writing `count` -- those decide where the
 * members after them start. Use the setters at the end of this
 * struct's section, which bump the message generation; a stale view
 * is then caught on use in a SITU_CHECKED build.
 *
 * Re-acquire the view after any such write.
 *
 * `order` also decides where later members start, and arrives
 * as an argument rather than as bytes: pass a different one and
 * the accessors answer differently on the spot. Nothing writes it,
 * so no view goes stale.
 */
/** Acquire a view. This struct is a frame: its extent depends on the
 * data, so the caller supplies the length they have and the bounds
 * check is made against that. The fields at a static offset are then
 * constant offsets from the base; the rest resolve through their own
 * offset functions below.
 */
static inline situ_err_t fzn_exif_ifd_view(const situ_msg_t *msg, uint32_t offset, uint32_t length,
		situ_view_t *out)
{
	if (length < FZN_EXIF_IFD_SIZE_MIN) {
		return SITU_ERR_BOUNDS;
	}

	return situ_view_at(msg, offset, length, out);
}

/* No accessor for `order`: it is a `parameter`,
 * which the caller supplies and which occupies no bytes.
 * The accessors of this struct that read it take it as a
 * trailing argument. */

/** ifd.count : u16  at AbsoluteStatic(0x00)
 * size=Fixed(2) align=Aligned(8) repr=ConditionallyConverted(order) atomic=AtomicWord mutate=InPlaceFixed
 */
static inline uint16_t fzn_exif_ifd_count_get(situ_view_t view, uint16_t arg_order)
{
	return (uint16_t)((arg_order == 0x4949u) ? situ_get_le16(situ_base(view) + 0u) : situ_get_be16(situ_base(view) + 0u));
}
/* No plain setter: `count` decides where later members
 * start, so writing it must invalidate outstanding views. Use
 * fzn_exif_ifd_count_set(),
 * which takes the message and bumps its generation. */

/** ifd.entries : ifd_entry  at AbsoluteStatic(0x02)
 * size=Bounded(0, 786420) align=Aligned(2) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting
 */
static inline uint32_t fzn_exif_ifd_entries_count(situ_view_t view, uint16_t arg_order)
{
	return (uint32_t)situ_nonneg_u32(situ_leaf_u64((arg_order == 0x4949u) ? situ_get_le16(situ_base(view) + 0u) : situ_get_be16(situ_base(view) + 0u)));
}
static inline situ_err_t fzn_exif_ifd_entries_at(situ_view_t view, uint32_t index, situ_view_t *out, uint16_t arg_order)
{
	const uint32_t stride = FZN_EXIF_IFD_ENTRY_SIZE_FIXED;
	const uint32_t base   = 2u;

	if (index >= fzn_exif_ifd_entries_count(view, arg_order)) {
		return SITU_ERR_BOUNDS;
	}

	return situ_view_sub(view, base + index * stride, stride, out);
}

/* No accessor for `order`: it is a `parameter`,
 * which the caller supplies and which occupies no bytes.
 * The accessors of this struct that read it take it as a
 * trailing argument. */

/** ifd.next : u32  at Dynamic
 * size=Fixed(4) align=Unaligned repr=ConditionallyConverted(order) atomic=NonAtomic mutate=InPlaceFixed
 */
static inline uint32_t fzn_exif_ifd_next_offset(situ_view_t view, uint16_t arg_order)
{
	uint32_t offset = 2u;
	offset = situ_advance_u32(offset, ((uint32_t)situ_nonneg_u32(situ_leaf_u64((arg_order == 0x4949u) ? situ_get_le16(situ_base(view) + 0u) : situ_get_be16(situ_base(view) + 0u))) * 12u), view.limit);

	return offset;
}
/** Zero where the member does not fit the view: its offset is a sum of
 * lengths the message chose, so the frame is not known to hold it, and
 * `validate` reports such a message as malformed (26.27).
 */
static inline uint32_t fzn_exif_ifd_next_get(situ_view_t view, uint16_t arg_order)
{
	return situ_in_bounds(view, fzn_exif_ifd_next_offset(view, arg_order), 4u)
		? (uint32_t)((arg_order == 0x4949u) ? situ_get_le32((situ_base(view) + fzn_exif_ifd_next_offset(view, arg_order)) + 0u) : situ_get_be32((situ_base(view) + fzn_exif_ifd_next_offset(view, arg_order)) + 0u))
		: (uint32_t)0;
}
/** Does nothing where the member does not fit the view: its offset is a
 * sum of lengths the message chose, and writing past the frame is
 * somebody else's data. `validate` reports such a message (26.27).
 */
static inline void fzn_exif_ifd_next_set(situ_view_t view, uint16_t arg_order, uint32_t value)
{
	if (situ_in_bounds(view, fzn_exif_ifd_next_offset(view, arg_order), 4u)) {
		if ((arg_order == 0x4949u)) {
		situ_put_le32((situ_base(view) + fzn_exif_ifd_next_offset(view, arg_order)) + 0u, (uint32_t)value);
	} else {
		situ_put_be32((situ_base(view) + fzn_exif_ifd_next_offset(view, arg_order)) + 0u, (uint32_t)value);
	}
	}
}

/** How many bytes a whole `ifd` needs, given `have` of them.
 *
 * SITU_OK            a complete one is present; *need is its length
 * SITU_ERR_TRUNCATED not yet; *need is a lower bound on the total
 *
 * For framing a stream: read, ask, read the difference, ask again. The
 * length fields are read only once the bytes holding them have arrived,
 * which is the case every hand-written version of this gets wrong.
 */
static inline situ_err_t fzn_exif_ifd_required(const uint8_t *data, uint32_t have, uint32_t *need, uint16_t arg_order)
{
	uint32_t at = 6u;
	uint32_t pos = 2u;
	situ_view_t view;

	/* A view over what has arrived, so every length expression below
	 * reads through the same bounds the accessors do. */
	view.base       = (uint8_t *)(uintptr_t)(const void *)data;
	view.limit      = have;
	view.generation = 0u;
	view.owner      = NULL;

	/* ifd.entries: reading its length means reading bytes that
	 * have to be here first. */
	if (have < pos) {
		*need = at;
		return SITU_ERR_TRUNCATED;
	}
	{
		const uint32_t len = situ_need_mul_u32((uint32_t)situ_nonneg_u32(situ_saturate_i64((arg_order == 0x4949u) ? situ_get_le16(situ_base(view) + 0u) : situ_get_be16(situ_base(view) + 0u))), 12u);

		at = situ_need_u32(at, len);
	}

	*need = at;
	return have >= at ? SITU_OK : SITU_ERR_TRUNCATED;
}

/** What `ifd.entries` hands `ifd_entry.order`: pass
 * it to the accessors on the view you take of it.
 */
static inline uint16_t fzn_exif_ifd_entries_arg_order(situ_view_t view, uint16_t arg_order)
{
	(void)view;
	return (uint16_t)(arg_order);
}

/** Writing any of these changes where later members start, so each
 * one bumps the message generation and invalidates outstanding
 * views. In a SITU_CHECKED build a stale view is then caught on
 * use; in a release build the check compiles out.
 */
static inline void fzn_exif_ifd_count_set(situ_msg_t *msg, situ_view_t view, uint16_t arg_order, uint16_t value)
{
	if ((arg_order == 0x4949u)) {
		situ_put_le16(situ_base(view) + 0u, (uint16_t)value);
	} else {
		situ_put_be16(situ_base(view) + 0u, (uint16_t)value);
	}
	situ_msg_touch(msg);
}

/** Check every constraint this schema states: [must_eq], [max],
 * [min], and the reserved-bit policy. Called on parse under
 * SITU_CHECKED, and available explicitly in any build.
 */
situ_err_t fzn_exif_ifd_validate(situ_view_t view, uint16_t arg_order);

/** The same walk, naming the member that refused. `*which` is one
 * of the ids below on a refusal and 0xFFFFFFFF when nothing
 * refused -- it is written either way, so a caller must not
 * expect its own value to survive the call. NULL asks for
 * the verdict alone. The id is the contract and the name is
 * a macro, so nothing here costs a string (0051).
 */
situ_err_t fzn_exif_ifd_check(situ_view_t view, uint32_t *which, uint16_t arg_order);
